    public static void show(String label, Object s) {
        System.out.println("=== " + label + " ===");
        System.out.println(s);
        System.out.println("--- escaped ---");
        System.out.println(((String)s).replace("\n", "\\n\n"));
        System.out.println();
    }

    public static void main(String[] args) {
        show("empty", new ReflectionToStringBuilder(new Empty(), new MultilineRecursiveToStringStyle()).toString());

        Simple sObj = new Simple(); sObj.value = 42;
        show("simple", new ReflectionToStringBuilder(sObj, new MultilineRecursiveToStringStyle()).toString());

