        n1.child = n2;
        show("chain", new ReflectionToStringBuilder(n1, new MultilineRecursiveToStringStyle()).toString());

        // Null value test
        Simple nullTest = null;
        try {
            new ReflectionToStringBuilder(nullTest, new MultilineRecursiveToStringStyle()).toString();
        } catch (Exception e) {
            System.out.println("null object -> exception: " + e);
        }

        // appendDetail(Object) with null value directly? value.getClass() would NPE
        MultilineRecursiveToStringStyle style = new MultilineRecursiveToStringStyle();
        try {
            StringBuffer buf = new StringBuffer();
            style.appendDetail(buf, "f", (Object) null);
            System.out.println("appendDetail null object -> buf=" + buf);
        } catch (Exception e) {
            System.out.println("appendDetail null object -> exception: " + e);
        }
    }
}
